"""Session tokens: generated by the OS CSPRNG, stored only as SHA-256 digests."""

import hashlib
import re
import secrets

TOKEN_BYTES = 32  # 256 bits of entropy
# token_urlsafe(32) yields 43 characters of the URL-safe base64 alphabet.
_TOKEN_PATTERN = re.compile(r"^[A-Za-z0-9_-]{43}$")


def new_token() -> str:
    """A fresh session token for the cookie. Never stored server-side."""
    return secrets.token_urlsafe(TOKEN_BYTES)


def is_well_formed(token: str) -> bool:
    """Cheap shape check, so arbitrary cookie values never reach the database."""
    return _TOKEN_PATTERN.fullmatch(token) is not None


def hash_token(token: str) -> bytes:
    """The value stored in auth.sessions.token_hash.

    A fast hash is safe here (unlike for passwords): the token has full
    256-bit entropy, so it cannot be brute-forced, and lookups need a
    deterministic digest.
    """
    return hashlib.sha256(token.encode("ascii")).digest()
